"""Actual shared celestial editor over synthetic Auth/RPCs; never live Supabase."""
import json


def run_alpha_editor_checks(*, cdp, e, check, wait_for, shot):
    q = json.dumps
    cdp.call('Emulation.setDeviceMetricsOverride', width=1440, height=900, deviceScaleFactor=1, mobile=False)
    e('new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)))')
    if e('document.getElementById("hierarchy-sidebar").hidden'):
        e('document.getElementById("sidebar-toggle").click()')
    def click(id):
        e(f'document.getElementById({q(id)}).click()')
    def submit(name):
        e(f'document.getElementById("entry-name").value={q(name)};document.getElementById("add-entry-form").requestSubmit()')
    def saved():
        wait_for('travelAlpha.getState().writeStatus==="saved"&&!document.getElementById("add-entry-dialog").open')
    def reopen():
        cdp.call('Page.reload', ignoreCache=True)
        wait_for('document.readyState==="complete"&&typeof travelAlpha!=="undefined"&&alphaAuth.getState().ready&&!!travelAlpha.getState().user')
        check(e('travelAlpha.getState().dataset.kind==="preview"'), 'session restoration does not silently select a dataset')
        click('alpha-refresh')
        wait_for('travelAlpha.getState().status==="universes-available"')
        e('document.querySelector("#alpha-datasets button").click()')
        wait_for('travelAlpha.getState().status==="loaded"&&!travelAlpha.getState().readOnly')
    check(e('!document.getElementById("alpha-new-galaxy").disabled&&document.getElementById("alpha-add-item").disabled'), 'only New Galaxy is enabled before selecting a body')
    click('alpha-new-galaxy');submit('Mexico');saved()
    root = e('travelAlpha.getState().dataset.snapshot.entries.find(r=>r.name==="Mexico").id')
    check(e(f'document.querySelector(".entry-node[data-entry-id=\\"{root}\\"]").dataset.body==="galaxy"&&!!document.querySelector(".entry-node .galaxy-core")'), 'acknowledged Galaxy uses the existing celestial renderer')
    click('alpha-add-item');submit('Hotel');saved()
    child = e('travelAlpha.getState().dataset.snapshot.entries.find(r=>r.name==="Hotel").id')
    check(e(f'document.querySelector(".entry-node[data-entry-id=\\"{child}\\"]").dataset.body==="sun"&&travelAlpha.getState().dataset.snapshot.entries.find(r=>r.id==={q(child)}).parentId==={q(root)}'), 'child Item renders as a Sun under its Galaxy')
    click('alpha-rename-item');submit('Oaxaca hotel');saved()
    check(e('document.getElementById("alpha-selected-name").textContent==="Oaxaca hotel"&&document.getElementById("alpha-save-state").textContent==="Saved"'), 'modal rename publishes the acknowledged name and Saved state')
    # Exercise the existing HierarchySidebar inline editor, not only the modal.
    e(f'document.querySelector(".hierarchy-row[data-entry-id=\\"{child}\\"] .tree-name").dispatchEvent(new MouseEvent("dblclick",{{bubbles:true}}))')
    wait_for('!!document.querySelector(".tree-rename")')
    e('const rename=document.querySelector(".tree-rename");rename.value="Oaxaca stay";rename.dispatchEvent(new KeyboardEvent("keydown",{key:"Enter",bubbles:true}))')
    wait_for('!document.querySelector(".tree-rename")&&document.getElementById("alpha-selected-name").textContent==="Oaxaca stay"')
    check(e('travelAlpha.getState().writeStatus==="saved"'), 'shared sidebar inline rename also waits for cloud acknowledgement')
    # Discard the acknowledged app cache so reload must obtain the mock server's
    # independent metadata rather than simply redisplay cached bodies.
    e('for(const key of Object.keys(localStorage))if(key.startsWith("cosmifold:travel-alpha:cache:"))localStorage.removeItem(key)')
    reopen()
    check(e('travelAlpha.getState().dataset.snapshot.entries.some(r=>r.name==="Oaxaca stay")&&document.querySelectorAll(".entry-node").length===2&&alphaFixture.calls.every(c=>c.name!=="cosmifold_commit_metadata")'), 'hard reload without app cache restores Galaxy/Item names from authoritative mock reads, without writes')
    e(f'document.querySelector(".entry-node[data-entry-id=\\"{child}\\"]").click()')
    def save_notes(text):
        click('alpha-edit-notes')
        e('document.getElementById("alpha-notes-input").value='+q(text)+';document.getElementById("alpha-notes-form").requestSubmit()')
    note='  Check in at 15:00\nBring booking confirmation 🧳\n<script>plain text only</script>  '
    check(e('!document.getElementById("alpha-notes").hidden&&document.getElementById("alpha-notes-text").textContent==="No notes yet."'), 'selected Item has an empty plain-text notes view')
    click('alpha-edit-notes');e('document.getElementById("alpha-notes-input").value="Discard this draft"');click('alpha-notes-cancel')
    check(e('document.getElementById("alpha-notes-text").textContent==="No notes yet."&&alphaFixture.calls.every(c=>c.name!=="cosmifold_commit_metadata")'), 'Cancel discards the unsaved note without a cloud write')
    e('alphaFixture.mode="hold"');save_notes(note)
    wait_for('typeof alphaFixture.release==="function"')
    check(e('document.getElementById("alpha-save-state").textContent==="Saving…"&&document.getElementById("alpha-notes-text").textContent==="No notes yet."&&document.getElementById("alpha-notes-input").disabled&&document.getElementById("alpha-notes-save").disabled'), 'notes remain acknowledged-only while Saving and duplicate editing is blocked')
    e('alphaFixture.release();alphaFixture.mode="ok"')
    wait_for('!document.getElementById("alpha-notes-dialog").open&&travelAlpha.getState().writeStatus==="saved"')
    check(e('document.getElementById("alpha-notes-text").textContent==='+q(note)+'&&!document.querySelector("#alpha-notes-text script")'), 'notes preserve Unicode/newlines/whitespace and render markup as text')
    reopen();e(f'document.querySelector(".entry-node[data-entry-id=\\"{child}\\"]").click()')
    check(e('document.getElementById("alpha-notes-text").textContent==='+q(note)), 'notes survive a hard refresh and authoritative reopen')
    e('alphaFixture.mode="unknown";alphaFixture.receiptMode="unavailable"');save_notes('Original receipt recovered notes')
    wait_for('travelAlpha.getState().writeStatus==="unresolved"')
    note_operation=e('alphaFixture.calls.filter(c=>c.name==="cosmifold_commit_metadata").at(-1).params.p_command.operationId')
    check(e('document.getElementById("alpha-notes-text").textContent==='+q(note)+'&&document.getElementById("alpha-notes-save").disabled&&document.getElementById("alpha-notes-input").disabled&&document.getElementById("alpha-notes-error").textContent.startsWith("Unresolved")'), 'uncertain note stays Unresolved with its confirmed preview and disabled editor')
    reopen();e(f'document.querySelector(".entry-node[data-entry-id=\\"{child}\\"]").click()')
    check(e('document.getElementById("alpha-notes-text").textContent==="Original receipt recovered notes"&&alphaFixture.calls.every(c=>c.name!=="cosmifold_commit_metadata")&&alphaFixture.calls.some(c=>c.name==="cosmifold_operation_receipt"&&c.params.p_operation_id==='+q(note_operation)+')'), 'notes recover the original operation receipt after refresh without another commit')
    e('alphaFixture.mode="hold"');click('alpha-rename-item');submit('Held acknowledgement')
    wait_for('typeof alphaFixture.release==="function"')
    count = e('alphaFixture.calls.filter(c=>c.name==="cosmifold_commit_metadata").length')
    check(e('document.getElementById("alpha-save-state").textContent==="Saving…"&&document.getElementById("alpha-selected-name").textContent==="Oaxaca stay"&&document.getElementById("alpha-new-galaxy").disabled&&document.getElementById("entry-submit").disabled'), 'Saving retains the confirmed name and disables duplicate editing')
    e('document.getElementById("add-entry-form").requestSubmit()')
    check(e('alphaFixture.calls.filter(c=>c.name==="cosmifold_commit_metadata").length') == count, 'duplicate form submission sends no second cloud operation')
    e('alphaFixture.release();alphaFixture.mode="ok"');saved()
    check(e('document.getElementById("alpha-selected-name").textContent==="Held acknowledgement"'), 'delayed acknowledgement publishes exactly the saved name')
    e('alphaFixture.mode="reject"');click('alpha-rename-item')
    e('document.getElementById("add-entry-dialog").close();document.getElementById("alpha-rename-item").click();new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)))')
    check(e('document.getElementById("add-entry-dialog").open&&document.getElementById("entry-name").value==="Held acknowledgement"'), 'a queued close event cannot clear a newly reopened rename form')
    submit('Rejected name')
    try:
        wait_for('travelAlpha.getState().writeStatus==="failed"&&!document.getElementById("entry-form-error").hidden')
    except AssertionError as failure:
        raise AssertionError('Alpha rejection UI: '+q(e('({write:travelAlpha.getState().writeStatus,error:travelAlpha.getState().error,context:travelAlpha.getState().dataset.context,selected:document.getElementById("alpha-selected-name").textContent,open:document.getElementById("add-entry-dialog").open,input:document.getElementById("entry-name").value,errorHidden:document.getElementById("entry-form-error").hidden,calls:alphaFixture.calls.map(c=>c.name)})'))) from failure
    check(e('document.getElementById("alpha-save-state").textContent.startsWith("Failed")&&!document.getElementById("entry-form-error").hidden&&document.getElementById("alpha-selected-name").textContent==="Held acknowledgement"'), 'definite write failure stays explicit and does not change the body name')
    click('alpha-entry-cancel');e('alphaFixture.mode="ok";alphaFixture.bump(travelAlpha.getState().dataset.scope.universeId)')
    click('alpha-rename-item');submit('Stale revision')
    wait_for('travelAlpha.getState().writeStatus==="failed"&&travelAlpha.getState().readOnly')
    check(e('document.getElementById("alpha-new-galaxy").disabled&&document.getElementById("alpha-rename-item").disabled'), 'stale revision blocks further edits instead of overwriting remote data')
    click('alpha-entry-cancel');click('alpha-reload')
    wait_for('travelAlpha.getState().status==="loaded"&&!travelAlpha.getState().readOnly')
    e(f'document.querySelector(".entry-node[data-entry-id=\\"{child}\\"]").click()')
    e('alphaFixture.mode="unknown";alphaFixture.receiptMode="unavailable"');click('alpha-rename-item');submit('Recovered after reload')
    wait_for('travelAlpha.getState().writeStatus==="unresolved"')
    operation = e('alphaFixture.calls.filter(c=>c.name==="cosmifold_commit_metadata").at(-1).params.p_command.operationId')
    check(e('document.getElementById("alpha-save-state").textContent.startsWith("Unresolved")&&document.getElementById("alpha-new-galaxy").disabled&&document.getElementById("alpha-selected-name").textContent==="Held acknowledgement"'), 'lost response and unavailable receipt show Unresolved with confirmed content and editing blocked')
    reopen()
    check(e('travelAlpha.getState().dataset.snapshot.entries.some(r=>r.name==="Recovered after reload")&&alphaFixture.calls.every(c=>c.name!=="cosmifold_commit_metadata")&&alphaFixture.calls.some(c=>c.name==="cosmifold_operation_receipt"&&c.params.p_operation_id==='+q(operation)+')'), 'reload recovers the exact original receipt without resending the interrupted save')
    e(f'document.querySelector(".entry-node[data-entry-id=\\"{child}\\"]").click();alphaFixture.mode="hold"')
    click('alpha-rename-item');submit('Request interrupted by reload')
    wait_for('typeof alphaFixture.release==="function"')
    reopen()
    check(e('travelAlpha.getState().dataset.snapshot.entries.some(r=>r.name==="Request interrupted by reload")&&alphaFixture.calls.every(c=>c.name!=="cosmifold_commit_metadata")'), 'page reload during Saving reconciles the committed operation without creating another write')
    e(f'document.querySelector(".entry-node[data-entry-id=\\"{child}\\"]").click();alphaFixture.mode="hold"')
    click('alpha-rename-item');submit('Account A private name')
    wait_for('typeof alphaFixture.release==="function"')
    e('alphaFixture.switchUser(alphaFixture.B)')
    check(e('travelAlpha.getState().user.id===alphaFixture.B&&document.querySelectorAll(".entry-node,.hierarchy-row").length===0&&!document.getElementById("add-entry-dialog").open&&document.getElementById("entry-name").value===""&&!document.body.textContent.includes("Account A private name")'), 'account switch immediately removes A bodies, hierarchy, selection and form draft')
    e('alphaFixture.release();alphaFixture.mode="ok"')
    wait_for('!travelAlpha.getState().writing')
    check(e('travelAlpha.getState().dataset.kind==="preview"&&travelAlpha.getState().writeStatus==="idle"'), 'late A acknowledgement cannot publish a body or save state into B')
    click('alpha-create');wait_for('travelAlpha.getState().status==="loaded"&&!travelAlpha.getState().creating')
    click('alpha-new-galaxy');submit('B private trip');saved()
    check(e('travelAlpha.getState().dataset.snapshot.entries.length===1&&travelAlpha.getState().dataset.snapshot.entries[0].name==="B private trip"&&!document.body.textContent.includes("Account A private name")'), 'B can edit only its separately owned Universe')
    e('alphaFixture.switchUser(alphaFixture.A)');click('alpha-refresh')
    wait_for('travelAlpha.getState().status==="universes-available"')
    e('document.querySelector("#alpha-datasets button").click()')
    wait_for('travelAlpha.getState().status==="loaded"&&!travelAlpha.getState().readOnly')
    check(e('travelAlpha.getState().dataset.snapshot.entries.some(r=>r.name==="Account A private name")&&!travelAlpha.getState().dataset.snapshot.entries.some(r=>r.name==="B private trip")'), 'returning to A recovers only A pending operation and data')
    check(e('document.querySelector("fieldset[disabled]")&&[...document.querySelectorAll("fieldset[disabled] button")].every(b=>b.matches(":disabled"))&&typeof travelAlpha.deleteSubtree==="undefined"&&typeof travelAlpha.updateContent==="undefined"'), 'unsupported actions are disabled and no local editing fallback is exposed')
    before_unsupported = e('alphaFixture.calls.filter(c=>c.name==="cosmifold_commit_metadata").length')
    e('document.querySelectorAll("fieldset[disabled] button").forEach(button=>button.click());document.querySelector(".tree-disclosure").click();document.querySelector(".tree-disclosure").click()')
    check(e('[...document.querySelectorAll(".hierarchy-row")].every(row=>!row.draggable)') and e('alphaFixture.calls.filter(c=>c.name==="cosmifold_commit_metadata").length') == before_unsupported, 'unsupported buttons and sidebar rerenders cannot dispatch edits or enable moving')
    for width, height in [(1440,900),(390,844),(320,568)]:
        cdp.call('Emulation.setDeviceMetricsOverride', width=width, height=height, deviceScaleFactor=1, mobile=width<500)
        e('document.getElementById("galaxy").scrollIntoView({block:"center"})')
        check(e('document.documentElement.scrollWidth<=innerWidth&&document.getElementById("galaxy").getBoundingClientRect().width<=innerWidth&&document.querySelectorAll(".entry-node").length===2&&[...document.querySelectorAll(".hierarchy-row")].every(row=>!row.draggable)'), f'{width}px: shared editor and bodies fit within Alpha; moving stays disabled')
        e(f'document.querySelector(".entry-node[data-entry-id=\\"{child}\\"]").click()');click('alpha-edit-notes')
        check(e('document.getElementById("alpha-notes-dialog").getBoundingClientRect().width<=innerWidth&&document.getElementById("alpha-notes-input").getBoundingClientRect().width<=document.getElementById("alpha-notes-dialog").getBoundingClientRect().width&&getComputedStyle(document.getElementById("alpha-notes-input")).fontSize==="16px"'), f'{width}px: notes editor fits and uses touch-friendly text')
        click('alpha-notes-cancel')
        shot('alpha-editor-'+str(width))
    e('alphaFixture.mode="hold"');save_notes('Account A pending private notes')
    wait_for('typeof alphaFixture.release==="function"')
    e('alphaFixture.switchUser(alphaFixture.B)')
    check(e('document.getElementById("alpha-notes").hidden&&!document.getElementById("alpha-notes-dialog").open&&document.getElementById("alpha-notes-input").value===""&&document.getElementById("alpha-notes-text").textContent===""'), 'switching accounts during a note save clears confirmed notes and the in-flight draft')
    e('alphaFixture.release();alphaFixture.mode="ok"');e('new Promise(resolve=>setTimeout(resolve,20))')
    check(e('travelAlpha.getState().user.id===alphaFixture.B&&document.getElementById("alpha-notes-text").textContent===""&&travelAlpha.getState().dataset.kind==="preview"'), 'late note acknowledgement cannot publish Account A text into B')
    e('alphaFixture.switchUser(alphaFixture.A)');click('alpha-refresh');wait_for('travelAlpha.getState().status==="universes-available"')
    e('document.querySelector("#alpha-datasets button").click()');wait_for('travelAlpha.getState().status==="loaded"&&!travelAlpha.getState().readOnly')
    e(f'document.querySelector(".entry-node[data-entry-id=\\"{child}\\"]").click()')
    check(e('document.getElementById("alpha-notes-text").textContent==="Account A pending private notes"'), 'returning to A reconciles only the original pending note')
    click('alpha-edit-notes');e('document.getElementById("alpha-notes-input").value="Account A private draft";alphaFixture.switchUser(alphaFixture.B)')
    check(e('document.getElementById("alpha-notes").hidden&&!document.getElementById("alpha-notes-dialog").open&&document.getElementById("alpha-notes-input").value===""&&document.getElementById("alpha-notes-text").textContent===""&&document.getElementById("alpha-notes-item").textContent===""'), 'switching accounts clears note bodies, modal and unsaved draft immediately')
    e('alphaFixture.switchUser(alphaFixture.A)');click('alpha-refresh');wait_for('travelAlpha.getState().status==="universes-available"')
    e('document.querySelector("#alpha-datasets button").click()');wait_for('travelAlpha.getState().status==="loaded"&&!travelAlpha.getState().readOnly')
